"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["60805"],{14404(e,t,n){n.d(t,{Ay:()=>l,RM:()=>a});var o=n(74848),i=n(28453);let a=[{value:"Replies",id:"replies",level:3}];function s(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"kill-the-tathagata-and-feed-him-to-the-dogs",children:"Kill the Tathagata and Feed Him to the Dogs!"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2006/7/9 17:51:50"}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:'Do not for a moment think that the title "Kill the Tathagata and Feed Him to the Dogs" shows any disrespect toward Buddhism. This kind of topic is not some modern invention either \u2014 the great Buddhist masters of old said such things more than once. This is surely the most extraordinary phenomenon in all human history. In all religions, politics, academia, and the like, nothing comparable has ever appeared anywhere else.'}),"\n",(0,o.jsx)(t.p,{children:'No faith, religion, or theory has ever seriously proclaimed that its king, core, lord, or equivalent should be killed and fed to the dogs. Especially those faiths, religions, and theories where a single utterance can send countless living beings into suffering and wars that rage for centuries \u2014 for them, this is utterly incomprehensible. Apart from Buddhism, you will absolutely never find the phenomenon of "Kill the Tathagata and Feed Him to the Dogs!" And Buddhism \u2014 is not Buddhism, not a religion, not a theory, not a practice, not a faith; it is called Buddhism.'}),"\n",(0,o.jsx)(t.p,{children:'In truth, there is nothing extraordinary about this, nothing that needs explaining. Yet some still insist on explaining it as something meant to shatter the shackles of the mind and other such explainable phrases \u2014 it seems they all deserve to be killed and fed to the dogs. Encountering a Buddha, kill the Buddha; encountering a demon, kill the demon. If one can kill but does not, then it\'s all just a game of madness. All that talk of "Buddha and self are one," "Buddha and demon are one" \u2014 it\'s all old-womanish pacifier-Zen, all deserving to be killed and fed to the dogs. Only a Bodhisattva of the Tenth Ground can become the Great Demon King \u2014 how can realms below the Tenth Ground even glimpse the Great Demon King\'s domain? Those who would subdue demons are merely grasping at empty shadows \u2014 truly pitiable.'}),"\n",(0,o.jsx)(t.p,{children:"The universe's battles and turmoil are but an ant's play. The stupidity of humankind lies not in debates over good and evil, but in hearts too narrow and vision too limited. Trying to peer at heaven through a pinhole without even knowing what realm they're looking at, and then presumptuously pronouncing on heaven \u2014 they're worse than frogs in a well. \"Think neither good nor evil \u2014 at that very moment, what is your original face, Venerable Ming?\" That old firewood-gatherer Lu was really being too much of an old busybody. Even being killed and fed to the dogs would have let old Lu get off too easy \u2014 just let him go then! However, without old Lu's compassionate heart or Yunmen's methods, anyone who recklessly speaks of \"Kill the Tathagata and Feed Him to the Dogs!\" \u2014 even pouring out the waters of ten trillion Ganges rivers would be futile defense, for karmic consequences are never wrong."}),"\n",(0,o.jsx)(t.p,{children:'Better to first kill yourself and feed yourself to the dogs. If you can\'t even serve as dog food, then you really are good for nothing. And if you cannot even bear to be killed and fed to the dogs, then what\'s the point of saying "If I don\'t go to hell, who will?" Such a realm \u2014 how could those who generate a mind of "kill and feed to the dogs" at the mention of killing and feeding to the dogs possibly recognize it? That which can be killed will eventually be killed. The Tathagata \u2014 coming from nowhere, going to nowhere \u2014 what is there to kill? And what is there not to kill? Fools disturbing themselves \u2014 truly lamentable.'}),"\n",(0,o.jsx)(t.p,{children:'When you face any faith, first ask whether you can kill it and feed it to the dogs. A faith that cannot be killed and fed to the dogs is not worth believing in. Furthermore, a faith that can be believed in is not worth believing in. That which can be believed is believed because of the "can" \u2014 and since it\'s been believed, it can also be un-believed. So just kill it and feed it to the dogs! Faith \u2014 is not faith; it is called faith.'}),"\n",(0,o.jsx)(t.h3,{id:"replies",children:"Replies"}),"\n",(0,o.jsx)("div",{class:"blog-comment",children:(0,o.jsxs)(t.p,{children:[(0,o.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/7/9 23:02:22",(0,o.jsx)("br",{}),"\nThey all deserve to be killed and fed to the dogs!"]})})]})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(s,{...e})}):s(e)}},13330(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>c,frontMatter:()=>l,contentTitle:()=>h,toc:()=>d,assets:()=>r});var o=JSON.parse('{"id":"confucius/20060709","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/confucius/20060709.md","sourceDirName":"confucius","slug":"/confucius/20060709","permalink":"/en/confucius/20060709","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"20060709","title":"","hide_table_of_contents":true,"sidebar_label":"Beat the Tathagata to Death and Feed Him to the Dogs! (2006/7/9 17:51:50)"},"sidebar":"confuciusSidebar","previous":{"title":"The \'May Fourth\' Movement: A Massive Trap in China\'s Historical Development! (2006/5/7 23:00:07)","permalink":"/en/confucius/20060507"},"next":{"title":"Don\'t Pin Confucianism\'s \\"Human Nature Self-Endowed, Buddha Nature Human-Made\\" on Buddhism! (2006/7/26 12:42:56)","permalink":"/en/confucius/20060726"}}'),i=n(74848),a=n(28453),s=n(14404);let l={id:0x1321a25,title:"",hide_table_of_contents:!0,sidebar_label:"Beat the Tathagata to Death and Feed Him to the Dogs! (2006/7/9 17:51:50)"},h,r={},d=[...s.RM];function u(e){return(0,i.jsx)(s.Ay,{})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>l});var o=n(96540);let i={},a=o.createContext(i);function s(e){let t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);